import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/HT2.html","title":"HT2","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.03,"words":310},"filePathRelative":"HT2.md"}`),a={name:`HT2.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ht2" tabindex="-1"><a class="header-anchor" href="#ht2"><span>HT2</span></a></h1><p><a href="./サーフボード.html">サーフボード</a></p><h2 id="購入-2026-06-06-土" tabindex="-1"><a class="header-anchor" href="#購入-2026-06-06-土"><span>購入 2026-06-06 (土)</span></a></h2><p>メルカリで4.1万円で購入。</p><ul><li>長さ: 5&#39;10&quot;</li><li>幅: 18 3/4&quot;</li><li>厚さ: 2 3/8&quot;</li><li>ボリューム: 26.1l</li></ul><h2 id="乗ってみた、なかなかいい-2026-06-27-土" tabindex="-1"><a class="header-anchor" href="#乗ってみた、なかなかいい-2026-06-27-土"><span>乗ってみた、なかなかいい！ 2026-06-27 (土)</span></a></h2><p>頭くらいの掘れる波で乗ってみた。期待通りテイクオフの滑り出しが早く、掘れた大きい波でも乗れる。ただ長さに慣れず、もっとパドルしてから乗らなくてはいけない所で早く立ちすぎてしまうのが何本か。</p><p>ステップバックしないと全く板が動かないが、ステップバックすると自由に動かせて、レールも入っていい感じだ。 ボトムターンの時のレールも、なんというか、力を入れやすい。一度ニュートラルにちょっとしてふんってやると入る感じで、 軽く足先で入る感じではないけれどスピードがでている時にもちゃんと入れられて太いラインで走れる感じがある。いいね。 全体的に<a href="./UberDriverJp.html">UberDriverJp</a>より大きく動かないといけない。 それが大きな波ではちょうど良い。</p><p>掘れた所で立つ時も、テイクオフの段階で普段よりも前に進み波が掘れて来るよりも前に進んでいく感じがある。 そして前のセクションで掘れていてこれまでちょっと無理か？と思うようなセクションにも当てていけるようなパワーと伸びがある。 大きな波ではこっちの方がいいな、という感じがした。</p><p>多少ゆるくなった所でも失速せずに走るので、ホームの波でも使っていけそうだ。 たぶんハラくらいあれば使えて、ムネ以上だと調子いい感じかな。 ハラだと乗れはするが長さが邪魔になるので<a href="./UberDriverJp.html">UberDriverJp</a>の方がたぶん良い、という感じだと思う。</p><p>ハラ以上が確定しているシチュエーションで出していきたいな。まぁ台風や低気圧用だね。</p><h3 id="購入時の動機" tabindex="-1"><a class="header-anchor" href="#購入時の動機"><span>購入時の動機</span></a></h3><p>自分のメインの板が<a href="./UberDriverJp.html">UberDriverJp</a>で、これはかなりオールラウンドに乗れて気に入っている。 サイズもフェースが張ってるなら膝くらいから、頭オーバーくらいまでは問題無く乗れて、大きい方でかなり調子が良い。</p><p>だが、5&#39;6と短いのと、プレセボは軽いので面のガタツキを拾いやすく、風に少し弱い気はしている。</p><p>台風用に長くて少し重いボードが欲しいな、という事でHT 2かCI Proが欲しいなぁ、とメルカリを見ていて、ちょうど湘南で安く出ていたので購入。</p><h2 id="youtube等" tabindex="-1"><a class="header-anchor" href="#youtube等"><span>youtube等</span></a></h2><p>HT2が欲しいと思って調べている。（追記：結局買った）</p><ul><li><a href="https://www.youtube.com/watch?v=3crxrshK_YY" target="_blank" rel="noopener noreferrer">Sharpeye &quot;HT2&quot; &quot;Filipe Toledo Model&quot; Surfboard Review by Noel Salas Ep.57 - YouTube</a></li><li><a href="https://www.youtube.com/watch?v=vvwtiF8ygEY" target="_blank" rel="noopener noreferrer">【湘南炸裂】デカ波セッションの中、奇跡1本ゲットしちゃいました。。。 - YouTube</a> 河村海沙は 5&#39;10, ダブルくらい</li><li><a href="https://www.youtube.com/watch?v=QghoTgiKwOk" target="_blank" rel="noopener noreferrer">【大セッション後】パドル地獄。。台風スウェルガンガン来る鵠沼でサーフィンしてきた。 - YouTube</a> ムネカタの少しガタついたコンディション</li><li><a href="https://www.youtube.com/watch?v=az_65mJ33J4&amp;list=PLKioWZsttHYOGUY1iuoExSdPUo9DtymCi&amp;index=3" target="_blank" rel="noopener noreferrer">【良いバンク発見】地元後輩プロと、鵠沼でサーフィンセッション楽しんできた。 - YouTube</a> これは5&#39;95のスワロー。25l。オンショアのハラ</li><li><a href="https://www.youtube.com/watch?v=MERohuiJGFE&amp;list=PLKioWZsttHYOGUY1iuoExSdPUo9DtymCi&amp;index=38" target="_blank" rel="noopener noreferrer">【危険度マックス!!】3年ぶりの新島の波にわからされました。。。 - YouTube</a> HT2の5&#39;10 25.3、66kg時代。新島ショアブレイク、頭くらい</li></ul>`,18)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};